let products=[];let livingPackage=null;let offerBaseId='sofa';let offerPackageId='stuepakke';
function html(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function rateGrid(p){if(p.priceOnRequest)return '<p class="quote-only">Pris på forespørsel</p>';return `<div class="rate-grid"><div><span>Døgn</span><strong>${money(p.price)}</strong></div><div><span>Uke · 7 døgn</span><strong>${money(p.weekPrice??p.price*5)}</strong></div><div><span>Måned · 30 døgn</span><strong>${money(p.monthPrice??p.price*15)}</strong></div></div><p class="rate-caption">Foreløpige eksempelpriser inkl. mva.</p>`;}
function packageContents(p){return p.includes?`<ul class="package-contents">${p.includes.map(item=>`<li>${html(item)}</li>`).join('')}</ul>`:'';}
function packageSuggestion(inCart=false){return `<aside class="package-suggestion"><p class="eyebrow">SOFAEN KAN LEIES SOM PAKKE</p><h3>Vil du ha et komplett uttrykk?</h3><p>Legg til sofabord, puter, pledd og dekor som passer sammen.</p>${rateGrid(livingPackage)}<button class="text-button" data-detail="${livingPackage.id}">Se ${html(livingPackage.name)} ↗</button>${inCart?`<button class="button dark" data-upgrade>Bytt sofa til ${html(livingPackage.name)} ↗</button>`:''}</aside>`;}
function upgradeToPackage(){const pack=products.find(p=>p.id===offerPackageId);if(!pack)return;const base=pack.components.find(c=>c.id===offerBaseId);const baseCount=cart[offerBaseId]||0;const draft={...cart};delete draft[offerBaseId];const capacity=remaining(pack.id,draft,products);const requested=baseCount?Math.ceil(baseCount/(base?.quantity||1)):1;const count=Math.min(requested,capacity);if(!count){toast('Pakken kan ikke tilbys med valgt beholdning. Andre valgte objekter kan bruke samme lager.');return;}const consumed=count*(base?.quantity||1);if(baseCount>consumed)draft[offerBaseId]=baseCount-consumed;draft[pack.id]=(draft[pack.id]||0)+count;cart=normalizeBasket(draft,products);renderCart();renderProducts();if(el('detail').open)el('detail').close();toast('Forespørselen er oppdatert med '+pack.name);}

let offerShown=false;try{offerShown=sessionStorage.getItem('konsept-stuepakke-offered')==='yes';}catch{}
function showPackageOffer(){if(offerShown||!livingPackage)return;offerShown=true;try{sessionStorage.setItem('konsept-stuepakke-offered','yes');}catch{}el('detail').classList.remove('product-mode');el('detail').classList.add('offer-mode');el('detailContent').innerHTML=`<div class="offer-heading"><p class="eyebrow">SOFA LAGT TIL · ET TIPS TIL DEG</p><h2>Oppgrader til <em>${html(livingPackage.name)}?</em></h2></div><div class="offer-body"><figure><img src="assets/hero.jpg" alt="Illustrert inspirasjonsmiljø for Stuepakken"><figcaption>Illustrasjonsbilde · eksempelpakke</figcaption></figure><div><h3>${html(livingPackage.name)}</h3><p>Sofaen du valgte, med sofabord, tekstiler og dekor som passer sammen.</p>${packageContents(livingPackage)}${rateGrid(livingPackage)}<p class="hint">Én pakke per valgt sofa. Sofaen erstattes i forespørselen. Andre enkeltprodukter beholdes som tillegg.</p></div></div><div class="offer-actions"><button class="button button-outline" data-close="detail">Behold kun sofa</button><button class="button dark" data-upgrade>Oppgrader til ${html(livingPackage.name)}</button></div>`;if(!el('detail').open)el('detail').showModal();el('detail').scrollTop=0;}
document.getElementById('detail').addEventListener('close',()=>el('detail').classList.remove('offer-mode','product-mode'));

function addonPrice(p){return p.priceOnRequest?'Pris på forespørsel':`+${money(p.price)}/døgn per pakke`;}
function packageOptions(p){const options=(p.relatedAddOns||[]).map(id=>products.find(x=>x.id===id&&!x.isPackage)).filter(Boolean),bedding=options.some(x=>x.name.toLowerCase().includes('oppredning'));return options.length?`<fieldset class="rental-options"><legend>${bedding?'2. Ønsker du sengeoppredning i tillegg?':'2. Ønsker du tekstilpakke til sofaen?'}</legend><p class="hint">Valgfritt tillegg. Prisen kommer i tillegg til ${bedding?'produktet':'sofaen'}.</p><div class="addon-choices"><label class="addon-choice"><input type="radio" name="productAddon" value="" checked><span><strong>Nei takk</strong><small>Kun ${bedding?'produktet':'sofaen'}</small></span></label>${options.map(x=>`<label class="addon-choice"><input type="radio" name="productAddon" value="${x.id}" ${remaining(x.id,cart,products)<=0?'disabled':''}><span><strong>${html(x.name)}</strong><small>${addonPrice(x)}</small>${x.requiredProductQuantity?`<small>Krever ${x.requiredProductQuantity} ${x.requiredProductQuantity===1?'seng':'senger'} per sett.</small>`:''}${!bedding?`<small>${html(x.description)}</small>`:''}</span></label>`).join('')}</div><div id="beddingDetails" hidden><div class="selection-fields"><label>Antall ${bedding?'oppredningssett':'tekstilpakker'}<input id="addonQuantity" type="number" min="1" value="1" step="1"></label>${bedding?`<label>Farge på sengeoppredning<select id="beddingColor"><option>Hvit</option><option>Lys brun</option><option>Brun</option><option>Grønn</option></select></label>`:''}</div><div id="beddingDuvetGroup" hidden><label>Dyner til dobbel oppredning<select id="beddingDuvet"><option>Én dobbeltdyne</option><option>To enkeltdyner</option></select></label></div><p class="hint">${bedding?'Inkluderer laken, dyne(r), pute(r) og trekk. Ett dobbelt sett brukes til to ILSKOV-senger. Farge og tilgjengelighet bekreftes i tilbudet.':'Én pakke til ett sofaoppsett. Våre stylister velger puter og eventuelt pledd som passer til sofaen og ønsket uttrykk. Dere får et bilde av oppsettet som oppskrift for plasseringen.'}</p></div></fieldset>`:'';}
function selectedAddon(){return products.find(p=>p.id===document.querySelector('[name="productAddon"]:checked')?.value);}
function refreshSelection(){const content=el('detailContent'),button=content.querySelector('[data-add]'),base=products.find(p=>p.id===button?.dataset.add);if(!base||!el('productQuantity'))return;const quantity=Number(el('productQuantity').value),extra=selectedAddon(),extraQuantity=extra?Number(el('addonQuantity').value):0;let valid=Number.isInteger(quantity)&&quantity>0&&quantity<=remaining(base.id,cart,products);if(el('beddingDetails')){el('beddingDetails').hidden=!extra;el('beddingDuvetGroup').hidden=!extra?.name.toLowerCase().includes('dobbel');if(extra){el('addonQuantity').max=remaining(extra.id,cart,products);valid=valid&&Number.isInteger(extraQuantity)&&extraQuantity>0&&extraQuantity<=remaining(extra.id,cart,products);}}const requirementDraft={...cart,[base.id]:(cart[base.id]||0)+quantity};if(extra)requirementDraft[extra.id]=(requirementDraft[extra.id]||0)+extraQuantity;const requirementError=addonRequirementError(requirementDraft,products);valid=valid&&!requirementError;const total={price:base.price*quantity+(extra?.price||0)*extraQuantity,weekPrice:base.weekPrice*quantity+(extra?.weekPrice||0)*extraQuantity,monthPrice:base.monthPrice*quantity+(extra?.monthPrice||0)*extraQuantity,priceOnRequest:base.priceOnRequest||extra?.priceOnRequest};el('selectionTotals').innerHTML=valid?`<p class="selection-total-label">${quantity} × ${html(base.name)}${extra?` + ${extraQuantity} × ${html(extra.name)} <span>(tillegg)</span>`:''}</p>${rateGrid(total)}`:'<p class="hint">'+html(requirementError||'Velg et antall innenfor tilgjengelig beholdning.')+'</p>';button.disabled=!valid;button.textContent=extra?'Legg til produkt + tilvalg':`Legg til ${valid?quantity:''} ${base.isPackage?'pakke(r)':'stk.'}`;content.querySelector('[data-detail-step="-1"]').disabled=quantity<=1;content.querySelector('[data-detail-step="1"]').disabled=quantity>=remaining(base.id,cart,products);}
function isOakTable(p){return /^Spisebord, eikefarget, Ø(110|120) cm$/.test(p.name);}
function oakTables(){return products.filter(isOakTable).sort((a,b)=>a.name.localeCompare(b.name,'nb'));}
function oakTableOptions(p){return isOakTable(p)?`<div class="table-size-options"><label for="tableSize">Velg størrelse</label><select id="tableSize">${oakTables().map(t=>`<option value="${html(t.id)}" ${t.id===p.id?'selected':''}>${html(t.name.split(', ').at(-1))} · ${remaining(t.id,cart,products)} stk. tilgjengelig</option>`).join('')}</select><p class="hint">Illustrasjonsbilde. Modell, ben og eikefarge kan variere. Duk følger med og benyttes ved styling; bordene kan ha skjønnhetsfeil.</p></div>`:'';}
